import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";import{at as i,ct as a,dt as o,ft as s,gt as c,ht as l,it as u,lt as d,mt as f,ot as p,pt as m,st as h,ut as g}from"./chunks/assets.Bn6Ku4Bm.js";var _=JSON.parse(`{"title":"飞行视图工具栏","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"zh/qgc-user-guide/fly_view/fly_view_toolbar.md","filePath":"zh/qgc-user-guide/fly_view/fly_view_toolbar.md"}`),v={name:`zh/qgc-user-guide/fly_view/fly_view_toolbar.md`};function y(n,_,v,y,b,x){return e(),r(`div`,null,[..._[0]||=[t(`<h1 id="飞行视图工具栏" tabindex="-1">飞行视图工具栏 <a class="header-anchor" href="#飞行视图工具栏" aria-label="Permalink to “飞行视图工具栏”">​</a></h1><h2 id="视图" tabindex="-1">视图 <a class="header-anchor" href="#视图" aria-label="Permalink to “视图”">​</a></h2><p>工具栏左边的“Q”图标允许您在其他顶级视图中选择：</p><ul><li><strong><a href="./../plan_view/plan_view.html">Plan Flight</a>：</strong> 用于创建任务、地理栅栏和集结点</li><li><strong>分析工具：</strong> 用于日志下载、地理标记图像或查看遥测等事项的一组工具。</li><li><strong>车辆配置：</strong> 新车初始配置的各种选项。</li><li><strong>应用程序设置：</strong> QGroundControl应用程序本身的设置。</li></ul><p>When a newer stable version of QGroundControl is available, a blue update badge is shown at the top right of the &quot;Q&quot; icon, and the views dropdown shows an <strong>Update</strong> button which opens the download page. A message about the new version is shown once per new version. The check only runs in stable builds.</p><h2 id="工具栏指示器" tabindex="-1">工具栏指示器 <a class="header-anchor" href="#工具栏指示器" aria-label="Permalink to “工具栏指示器”">​</a></h2><p>Next are multiple toolbar indicators for vehicle status. 每个工具栏指示器的下拉功能提供了关于状态的更多细节。您也可以展开指示器以显示与指示器相关联的其他应用程序和载具设置。按&quot;&gt;&quot;按钮来扩展。</p><h3 id="flight-status" tabindex="-1">Flight Status <img src="data:image/png;base64," alt="Flight Status indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#flight-status" aria-label="Permalink to “Flight Status”">​</a></h3><p>飞行状态指示器显示载具是否可以飞行。它可以是下列状态之一：</p><ul><li><strong>准备好飞速</strong> (_绿色背景) - 载具已准备就绪。</li><li><strong>准备好飞行</strong> (_黄色背景) - 载具已准备好在当前飞行模式下飞行。但有些警告可能造成问题。</li><li><strong>尚未准备好</strong> - 载具没有准备好飞行，也不会起飞。</li><li><strong>解锁</strong> - 载具已解锁并准备起飞。</li><li><strong>飞行</strong> - 载具在空中飞行和飞行中。</li><li><strong>着陆</strong> - 载具正在着陆。</li><li><strong>通信丢失</strong> - QGroundControl已失去与载具的通信。</li></ul><p>The Flight Status indicator dropdown fills the window and also gives you access to:</p><ul><li><strong>解锁</strong> - 解锁一辆载具开启发动机以准备起飞。你只有在载具安全和准备飞行时才能解锁载具。通常你不需要手动解锁载具。你可以简单地起飞或开始执行任务，载具将解锁自己。</li><li><strong>Disarm</strong> - Disarming a vehicle stops the motors. For aircraft it is only available when the vehicle is on the ground. 一般来说，你无需明确进行锁定操作，因为飞行器会在着陆后自动锁定，或者如果在解锁后若未起飞，不久后也会自动锁定。</li><li><strong>Emergency Stop</strong> - Replaces <strong>Disarm</strong> while an aircraft is flying. It is a red button which you must press and hold to confirm. It stops the motors while in the air. 仅供紧急情况使用，你的飞行器会坠毁！ Ground vehicles and submarines keep the normal <strong>Disarm</strong> button.</li><li><strong>Force Arm</strong> - Arms the vehicle while bypassing pre-arm checks. Only shown when <strong>Allow Force Arm</strong> is enabled in <a href="./../settings_view/fly_view.html">Fly View Settings</a>.</li><li><strong>Reboot Vehicle</strong> - Shown at the right when the vehicle needs a reboot (see <a href="#vehicle-reboot-required">Vehicle Reboot Required</a>).</li><li><strong>Firmware update available</strong> - Shown when the vehicle is not running the latest stable firmware (see <a href="#firmware-update-available">Firmware Update Available</a>).</li><li><strong>Vehicle Messages</strong> - The messages sent by the vehicle. Unread messages are shown in bold. Use <strong>Mark as Read</strong> to mark them all as read, or <strong>Clear</strong> to delete them.</li></ul><p>在警告或尚未准备好状态的情况下，您可以点击指示器来显示下拉菜单，显示原因(s)。右侧的切换按钮会展开每个错误，并显示更多信息及可能的解决方案。</p><p>每个问题解决后，将从用户界面中消失。当所有阻止解锁的问题被移除时，你现在应该可以准备飞行了。</p><h3 id="flight-mode" tabindex="-1">Flight Mode <img src="`+c+`" alt="Flight Mode indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#flight-mode" aria-label="Permalink to “Flight Mode”">​</a></h3><p>飞行模式指示器显示您当前的飞行模式。下拉菜单允许您在飞行模式之间切换。扩展页面允许您：</p><ul><li>配置载具降落设置</li><li>设置全局地理栅栏设置</li><li>从显示列表中添加/删除飞行模式</li></ul><h3 id="flight-status-badges" tabindex="-1">Flight Status Badges <a class="header-anchor" href="#flight-status-badges" aria-label="Permalink to “Flight Status Badges”">​</a></h3><p><img src="`+l+`" alt="Flight Status badges" width="448" height="102"></p><p>Small badges can appear at the top right of the Flight Status indicator: a blue update icon when newer stable vehicle firmware is available, an orange power icon when the vehicle needs a reboot, and a status label showing the most severe issue across the dropdown tabs. Click the indicator to open the dropdown and act on them.</p><p>The status label shows the worst of:</p><ul><li><strong>Error</strong> (<em>red</em>) - Unread critical vehicle messages, or health and arming check errors.</li><li><strong>Warning</strong> (<em>orange</em>) - Unread warning or notice messages, health and arming check warnings, or an incomplete <a href="./fly_tools.html#preflight-checklist">Pre-Flight Checklist</a> while the vehicle is disarmed.</li><li><strong>Info</strong> (<em>blue</em>) - Other unread vehicle messages.</li></ul><h4 id="vehicle-messages" tabindex="-1">Vehicle Messages <a class="header-anchor" href="#vehicle-messages" aria-label="Permalink to “Vehicle Messages”">​</a></h4><p>Opening the dropdown does not mark messages as read. Press <strong>Mark as Read</strong> in the message list to clear their contribution to the status label while keeping the messages, or use <strong>Clear</strong> to delete the messages. Health and arming check issues and an incomplete checklist keep the label shown until they are resolved.</p><p>In the dropdown message list, unread messages are shown in bold and read messages in normal weight. Critical messages are shown in red and warnings and notices in orange. New messages are always unread, even after earlier ones were marked as read.</p><p>Critical messages are also shown in a <strong>Vehicle Alert</strong> popup below the toolbar. Up to 5 messages are shown at once, fewer if the window is too short to fit them. If more arrive the popup title changes to <strong>Vehicle Alert - Click to see more</strong>, clicking it opens the Flight Status dropdown. The popup closes automatically after 10 seconds, or when you click it.</p><h4 id="vehicle-reboot-required" tabindex="-1">Vehicle Reboot Required <a class="header-anchor" href="#vehicle-reboot-required" aria-label="Permalink to “Vehicle Reboot Required”">​</a></h4><p>Some parameter changes and sensor calibrations only take effect after the vehicle reboots. When you make such a change an orange power icon is shown next to the status label, and stays there until the vehicle is rebooted. You can make several changes and reboot once at the end.</p><p>When a parameter change needs a reboot, a message also reminds you that the change will not take effect until the vehicle is rebooted. The message is not repeated for further changes made within 2 minutes.</p><p>To reboot, open the Flight Status dropdown and press and hold <strong>Reboot Vehicle</strong> on the right. The vehicle can only be rebooted while disarmed. If it is armed, the button is replaced by a reminder to disarm first.</p><h4 id="firmware-update-available" tabindex="-1">Firmware Update Available <a class="header-anchor" href="#firmware-update-available" aria-label="Permalink to “Firmware Update Available”">​</a></h4><p>When the vehicle connects, QGroundControl checks whether it is running the latest stable firmware release. The check only applies to official (non-development) firmware. If a newer stable release is available a blue update icon is shown at the top right of the Flight Status indicator, and the dropdown shows the current and latest stable versions.</p><p>A message about the out of date firmware is shown once for each new stable release. Press <strong>Acknowledge and Hide</strong> in the dropdown to hide the update icon. It stays hidden, across reconnects and restarts, until a newer stable release is available. The dropdown still shows the version information.</p><p>To update the firmware use <a href="./../setup_view/firmware.html">Vehicle Configuration &gt; Firmware</a>.</p><h3 id="gps" tabindex="-1">GPS <img src="`+f+`" alt="GPS indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#gps" aria-label="Permalink to “GPS”">​</a></h3><p>The GPS indicator shows satellite and GNSS status in the toolbar, and the dropdown provides additional GPS details.</p><p>While the vehicle reports GPS, the indicator shows its satellite count and HDOP. Otherwise it shows the connected <a href="./../settings_view/gnss_receiver.html">GNSS receiver</a>: the satellites it uses and its fix, or the state of a configured base station. A vertical <em>RTK</em> label appears while corrections for vehicles are configured or flowing (orange while they are awaited), and <em>GNSS</em> while only a GNSS receiver is connected; the label turns orange when the receiver reports jamming, spoofing or an antenna fault.</p><p>When the vehicle reports GPS resilience telemetry (authentication, spoofing, or jamming state), icons next to the indicator show the worse of the vehicle&#39;s GPS receivers, and the dropdown lists the state of each receiver that reports it.</p><p>The dropdown also shows the GNSS receiver status, the correction stream sent to vehicles, the NTRIP connection with a <strong>Connect</strong> button once a caster is configured, and the ground station position. Expand it for the <a href="./../settings_view/gnss_receiver.html#receiver">GNSS Receiver</a> settings.</p><h3 id="battery" tabindex="-1">Battery <img src="`+m+`" alt="Battery indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#battery" aria-label="Permalink to “Battery”">​</a></h3><p>电池指示器向您展示了一个可配置的充电图标。它也可以配置为显示剩余的电压或两种电压。扩展页面允许您：</p><ul><li>设定电池图标中显示的值 (s)</li><li>配置图标着色</li><li>设置低电量故障安全</li></ul><h3 id="remote-id" tabindex="-1">Remote ID <img src="`+s+`" alt="Remote ID indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#remote-id" aria-label="Permalink to “Remote ID”">​</a></h3><p>The Remote ID indicator appears when Remote ID is available on the active vehicle. Its color indicates overall Remote ID health, and the dropdown shows Remote ID status details.</p><h3 id="esc" tabindex="-1">ESC <img src="`+o+`" alt="ESC indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#esc" aria-label="Permalink to “ESC”">​</a></h3><p>The ESC indicator appears when ESC telemetry is available from the vehicle. It shows overall ESC health and online motor count, and opens a detailed ESC status page.</p><h3 id="joystick" tabindex="-1">Joystick <img src="`+g+`" alt="Joystick indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#joystick" aria-label="Permalink to “Joystick”">​</a></h3><p>The Joystick indicator appears when a joystick/gamepad is detected. The dropdown shows device status and connection details.</p><h3 id="telemetry-rssi" tabindex="-1">Telemetry RSSI <img src="`+d+`" alt="Telemetry RSSI indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#telemetry-rssi" aria-label="Permalink to “Telemetry RSSI”">​</a></h3><p>The Telemetry RSSI indicator appears when telemetry signal information is available. It provides local/remote RSSI and additional radio link quality details.</p><h3 id="rc-rssi" tabindex="-1">RC RSSI <img src="`+a+`" alt="RC RSSI indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#rc-rssi" aria-label="Permalink to “RC RSSI”">​</a></h3><p>The RC RSSI indicator appears when RC signal information is available. It shows current RC link strength and opens a page with RC RSSI details.</p><h3 id="gimbal" tabindex="-1">Gimbal <img src="`+h+`" alt="Gimbal indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#gimbal" aria-label="Permalink to “Gimbal”">​</a></h3><p>The Gimbal indicator is shown when the vehicle supports the <a href="https://mavlink.io/en/services/gimbal_v2.html" target="_blank" rel="noreferrer">MAVLink Gimbal Protocol</a>. It displays active gimbal status and provides access to gimbal controls and settings.</p><h3 id="vtol-transitions" tabindex="-1">VTOL Transitions <img src="`+p+`" alt="VTOL indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#vtol-transitions" aria-label="Permalink to “VTOL Transitions”">​</a></h3><p>For VTOL vehicles, a VTOL transition status indicator is shown when applicable. It indicates the current VTOL mode/state and provides transition-related status information.</p><h3 id="mavlink-signing" tabindex="-1">MAVLink Signing <a class="header-anchor" href="#mavlink-signing" aria-label="Permalink to “MAVLink Signing”">​</a></h3><p>The MAVLink Signing indicator appears when signing keys have been configured (see <a href="./../settings_view/telemetry.html#signing">MAVLink 2 Signing</a>). It shows a lock icon that indicates whether MAVLink 2 message signing is active on the current vehicle connection:</p><ul><li><strong>Locked (green):</strong> Signing is active — the vehicle&#39;s incoming packets matched a stored key, or a key was manually enabled.</li><li><strong>Unlocked:</strong> Signing is not active on the current connection.</li></ul><p>The dropdown shows the signing status, the name of the active key (if any), and the number of saved keys. Expanding the indicator provides full key management: you can enable a key on the vehicle, disable the active key, delete unused keys, or add new keys.</p><h3 id="multi-vehicle-selector" tabindex="-1">Multi-Vehicle Selector <img src="`+i+`" alt="Multi-Vehicle indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#multi-vehicle-selector" aria-label="Permalink to “Multi-Vehicle Selector”">​</a></h3><p>The Multi-Vehicle selector appears when more than one vehicle is connected. It allows you to quickly switch the active vehicle from the toolbar.</p><h3 id="apm-support-forwarding" tabindex="-1">APM Support Forwarding <img src="`+u+`" alt="APM Support Forwarding indicator" style="height:1.15em;vertical-align:text-bottom;"> <a class="header-anchor" href="#apm-support-forwarding" aria-label="Permalink to “APM Support Forwarding”">​</a></h3><p>On ArduPilot, an APM Support Forwarding indicator appears when MAVLink traffic forwarding to a support server is enabled.</p>`,64)]])}var b=n(v,[[`render`,y]]);export{_ as __pageData,b as default};